        "language": "KQL",
        "purpose": "SecurityAlert — Alert record",
        "query": "let lookback = 24h;\nSecurityAlert\n| where TimeGenerated > ago(lookback)\n| where AlertName has \"AWS Root Account Activity\"\n| project TimeGenerated, AlertName, AlertSeverity, ProviderName, CompromisedEntity, SystemAlertId, Description\n| order by TimeGenerated desc",
        "note": "Use when the alert is ingested into SecurityAlert. If no rows return, pivot to the native source table below.",
        "pivots": [
          {
            "source": "SecurityAlert — Alert record",
            "query": "let lookback = 24h;\nSecurityAlert\n| where TimeGenerated > ago(lookback)\n| where AlertName has \"AWS Root Account Activity\"\n| project TimeGenerated, AlertName, AlertSeverity, ProviderName, CompromisedEntity, SystemAlertId, Description\n| order by TimeGenerated desc",
            "note": "Use when the alert is ingested into SecurityAlert. If no rows return, pivot to the native source table below."
          },
          {
            "source": "SigninLogs — Interactive sign-ins",
            "query": "let lookback = 24h;\nSigninLogs\n| where TimeGenerated > ago(lookback)\n| where ResultType != \"0\"\n| project TimeGenerated, UserPrincipalName, IPAddress, AppDisplayName, ResourceDisplayName, ResultType, ResultDescription, ConditionalAccessStatus, CorrelationId\n| order by TimeGenerated desc",
            "note": "Review failed sign-ins, user, source IP, app/resource, result and Conditional Access status. Narrow by alert user/IP and time window."
          },
          {
            "source": "AADNonInteractiveUserSignInLogs — Non-interactive sign-ins",
            "query": "let lookback = 24h;\nAADNonInteractiveUserSignInLogs\n| where TimeGenerated > ago(lookback)\n| project TimeGenerated, UserPrincipalName, IPAddress, AppDisplayName, ResourceDisplayName, ResultType, ResultDescription, ConditionalAccessStatus, CorrelationId\n| order by TimeGenerated desc",
            "note": "Use for token/refresh/non-interactive sign-ins where this table is connected."
          },
          {
            "source": "AuditLogs — Identity and policy changes",
            "query": "let lookback = 24h;\nAuditLogs\n| where TimeGenerated > ago(lookback)\n| where Category =~ \"UserManagement\" or Category =~ \"Policy\" or OperationName has_any (\"Add\", \"Update\", \"Reset\", \"authentication\", \"Conditional Access\")\n| project TimeGenerated, Category, OperationName, Result, InitiatedBy, TargetResources, CorrelationId\n| order by TimeGenerated desc",
            "note": "Correlate nearby account, authentication-method, role or Conditional Access changes. Validate exact operation names in your tenant."
          }
        ]
